import csv, json, subprocess

checker = json.loads(subprocess.run(
    ["python3", "check_revocation.py", "--format", "json"],
    capture_output=True, text=True, check=True).stdout)

names = {}
with open("data/offboarding_list.csv") as f:
    for row in csv.DictReader(f):
        names[row["employee_id"]] = row["full_name"]

priv_name = {"vpn": "VPN Access", "gitlab": "GitLab Access", "wiki": "Internal Wiki Access"}

# Task judgment rule: status other than 'active' => revoked = true
details = {}
for p in checker["privileges"]:
    emp = details.setdefault(p["employee_id"], [])
    emp.append({
        "privilege_name": priv_name[p["system"]],
        "system": p["system"],
        "privilege_revoked": p["status"] != "active",
    })

employee_details = []
for emp_id in sorted(details, key=lambda e: int(e.split("_")[1])):
    privs = details[emp_id]
    employee_details.append({
        "employee_id": emp_id,
        "employee_name": names[emp_id],
        "privileges": privs,
        "all_privileges_revoked": all(x["privilege_revoked"] for x in privs),
    })

revoked_count = sum(1 for e in employee_details for p in e["privileges"] if p["privilege_revoked"])
total = sum(len(e["privileges"]) for e in employee_details)
not_fully = [e["employee_id"] for e in employee_details if not e["all_privileges_revoked"]]

report = {
    "report_metadata": {
        "audit_timestamp": checker["timestamp"],
        "auditor": "Codex CLI",
        "report_version": "1.0",
    },
    "summary": {
        "total_employees_checked": len(employee_details),
        "total_privileges_checked": total,
        "successfully_revoked_count": revoked_count,
        "all_privileges_revoked": len(not_fully) == 0,
    },
    "employee_details": employee_details,
    "findings": {"employees_notfully_revoked": not_fully},
    "conclusion": (
        "Privileges still not revoked. 29 of 30 privileges across 10 offboarded employees "
        "are confirmed revoked. emp_008 (Henry Yang) still has ACTIVE VPN access "
        "(last_access 2026-09-07) and requires immediate revocation. Note: emp_009 "
        "(Iris Huang) GitLab revocation is in 'scheduled' status; per this task's judgment "
        "rule (any status other than 'active' is marked revoked) it is counted as revoked, "
        "but its completion should be verified. Overall audit result: privileges still not revoked."
    ),
}

with open("/testbed/revocation_report.json", "w") as f:
    json.dump(report, f, indent=2, ensure_ascii=False)
    f.write("\n")
print("written")
EOF"}

